            <div class="ft-code-actions"><button class="glass tiny" id="ft-copy" type="button">${ce("copy",15)}<span>Copy code</span></button><button class="glass tiny" id="ft-link" type="button">${ce("link",15)}<span>Copy invite link</span></button><button class="glass tiny" id="ft-share" type="button" hidden>${ce("share",15)}<span>Share</span></button></div>
